TASK
Decorate a promise with timeout, fallback, and cancellation behavior.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pTimeout, named export TimeoutError.
pTimeout(inputPromise, options) returns a decorated promise with .clear() to cancel its timeout. milliseconds is a positive number; Infinity disables timeout. Before timeout, it adopts the input fulfillment or rejection. When timeout expires, default behavior rejects with TimeoutError; message may be a string, an Error to reject with, or false to resolve undefined. A fallback function can provide a value/promise instead, and exceptions from fallback reject the decorated promise. Cancelable input promises have their .cancel() method called on ordinary timeout.
customTimers supplies {setTimeout, clearTimeout} for controlled timing. The functions follow timer callback/delay and timer-handle conventions. A supplied AbortSignal cancels using its reason, including when already aborted. Settled operations clean up active timers and abort listeners. The input remains a promise whose rejection must be handled.

SOURCE index.js
   1: export class TimeoutError extends Error {
   2: 	name = 'TimeoutError';
   3: 
   4: 	constructor(message, options) {
   5: 		super(message, options);
   6: 		Error.captureStackTrace?.(this, TimeoutError);
   7: 	}
   8: }
   9: 
  10: const getAbortedReason = signal => signal.reason ?? new DOMException('This operation was aborted.', 'AbortError');
  11: 
  12: export default function pTimeout(promise, options) {
  13: 	const {
  14: 		milliseconds,
  15: 		fallback,
  16: 		message,
  17: 		customTimers = {setTimeout, clearTimeout},
  18: 		signal,
  19: 	} = options;
  20: 
  21: 	let timer;
  22: 	let abortHandler;
  23: 
  24: 	const wrappedPromise = new Promise((resolve, reject) => {
  25: 		if (typeof milliseconds !== 'number' || Math.sign(milliseconds) !== 1) {
  26: 			throw new TypeError(`Expected \`milliseconds\` to be a positive number, got \`${milliseconds}\``);
  27: 		}
  28: 
  29: 		if (signal?.aborted) {
  30: 			reject(getAbortedReason(signal));
  31: 			return;
  32: 		}
  33: 
  34: 		if (signal) {
  35: 			abortHandler = () => {
  36: 				reject(getAbortedReason(signal));
  37: 			};
  38: 
  39: 			signal.addEventListener('abort', abortHandler, {once: true});
  40: 		}
  41: 
  42: 		// Use .then() instead of async IIFE to preserve stack traces
  43: 		// eslint-disable-next-line promise/prefer-await-to-then, promise/prefer-catch
  44: 		promise.then(resolve, reject);
  45: 
  46: 		if (milliseconds === Number.POSITIVE_INFINITY) {
  47: 			return;
  48: 		}
  49: 
  50: 		// We create the error outside of `setTimeout` to preserve the stack trace.
  51: 		const timeoutError = new TimeoutError();
  52: 
  53: 		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
  54: 		timer = customTimers.setTimeout.call(undefined, () => {
  55: 			if (fallback) {
  56: 				try {
  57: 					resolve(fallback());
  58: 				} catch (error) {
  59: 					reject(error);
  60: 				}
  61: 
  62: 				return;
  63: 			}
  64: 
  65: 			if (typeof promise.cancel === 'function') {
  66: 				promise.cancel();
  67: 			}
  68: 
  69: 			if (message === false) {
  70: 				resolve();
  71: 			} else if (message instanceof Error) {
  72: 				reject(message);
  73: 			} else {
  74: 				timeoutError.message = message ?? `Promise timed out after ${milliseconds} milliseconds`;
  75: 				reject(timeoutError);
  76: 			}
  77: 		}, milliseconds);
  78: 	});
  79: 
  80: 	// eslint-disable-next-line promise/prefer-await-to-then
  81: 	const cancelablePromise = wrappedPromise.finally(() => {
  82: 		cancelablePromise.clear();
  83: 		if (abortHandler && signal) {
  84: 			signal.removeEventListener('abort', abortHandler);
  85: 		}
  86: 	});
  87: 
  88: 	cancelablePromise.clear = () => {
  89: 		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
  90: 		customTimers.clearTimeout.call(undefined, timer);
  91: 		timer = undefined;
  92: 	};
  93: 
  94: 	return cancelablePromise;
  95: }

